=== FILE: lifo4_fcov.sv ===
// lifo4_fcov: functional coverage model for the lifo4 stack block.
// Built from the approved requirement-to-plan matrix (traceability_matrix.md).
//
// CLOSURE STATEMENT
// Sampling: every rising edge of clk, on the port values just before the edge.
// count, empty and full describe the stack as it stood before the edge.
// Occupancy class from count: EMPTY = 0, MID = 1..3 (neither empty nor full), FULL = 4.
// Operation (rst_n high): PUSH = push & !pop, POP = pop & !push, BOTH = push & pop.
//
// Planned bins (15):
//   0  PUSH x EMPTY   LIFO-PUSH
//   1  PUSH x MID     LIFO-PUSH
//   2  PUSH x FULL    LIFO-OVERFLOW
//   3  POP  x EMPTY   LIFO-UNDERFLOW
//   4  POP  x MID     LIFO-POP
//   5  POP  x FULL    LIFO-POP
//   6  BOTH x EMPTY   LIFO-BOTH-EMPTY
//   7  BOTH x MID     LIFO-REPLACE
//   8  BOTH x FULL    LIFO-REPLACE
//   9  occupancy 0    (all)
//   10 occupancy 1    (all)
//   11 occupancy 2    (all)
//   12 occupancy 3    (all)
//   13 occupancy 4    (all)
//   14 reset (rst_n low) applied while count != 0   LIFO-RESET
//
// Exclusions: none. The matrix waives no scenario and names none unreachable.
// Hit flags are cleared only at time zero; rst_n does not clear coverage.

module lifo4_fcov (
    input  logic       clk, rst_n, push, pop,
    input  logic [7:0] din, dout,
    input  logic [2:0] count,
    input  logic       empty, full, err,
    output int         planned,   // how many bins the model plans
    output int         holes      // how many of them have not been hit yet
);

    localparam int NBINS = 15;

    logic [NBINS-1:0] hit;

    initial hit = '0;

    always @(posedge clk) begin
        if (rst_n === 1'b1) begin
            // operation x occupancy crosses
            if (push === 1'b1 && pop === 1'b0) begin
                if (count == 3'd0)                     hit[0] <= 1'b1;
                if (count >= 3'd1 && count <= 3'd3)    hit[1] <= 1'b1;
                if (count == 3'd4)                     hit[2] <= 1'b1;
            end
            if (push === 1'b0 && pop === 1'b1) begin
                if (count == 3'd0)                     hit[3] <= 1'b1;
                if (count >= 3'd1 && count <= 3'd3)    hit[4] <= 1'b1;
                if (count == 3'd4)                     hit[5] <= 1'b1;
            end
            if (push === 1'b1 && pop === 1'b1) begin
                if (count == 3'd0)                     hit[6] <= 1'b1;
                if (count >= 3'd1 && count <= 3'd3)    hit[7] <= 1'b1;
                if (count == 3'd4)                     hit[8] <= 1'b1;
            end
            // occupancy levels
            if (count == 3'd0) hit[9]  <= 1'b1;
            if (count == 3'd1) hit[10] <= 1'b1;
            if (count == 3'd2) hit[11] <= 1'b1;
            if (count == 3'd3) hit[12] <= 1'b1;
            if (count == 3'd4) hit[13] <= 1'b1;
        end else if (rst_n === 1'b0) begin
            // reset applied while the stack holds a word
            if (count >= 3'd1 && count <= 3'd4) hit[14] <= 1'b1;
        end
    end

    always_comb begin
        planned = NBINS;
        holes   = 0;
        for (int i = 0; i < NBINS; i++) begin
            if (!hit[i]) holes = holes + 1;
        end
    end

endmodule
